<?php

use Illuminate\Routing\Route;
use Illuminate\Support\Facades\Route as Router;

/*
 * docs/openapi.json is generated by Scramble (`composer docs:api`) and
 * committed. CI regenerates it and fails on a diff; this test catches the
 * simpler mistake of adding a route and not regenerating at all.
 */

function normalisePath(string $path): string
{
    return preg_replace('/\{[^}]+\}/', '{}', '/'.ltrim($path, '/'));
}

test('the OpenAPI document describes every API route', function () {
    $spec = json_decode(file_get_contents(base_path('docs/openapi.json')), true);

    $documented = collect($spec['paths'])
        ->flatMap(fn (array $ops, string $path) => collect(array_keys($ops))
            ->map(fn ($method) => strtoupper($method).' '.normalisePath('api'.$path)))
        ->sort()->values()->all();

    $routes = collect(Router::getRoutes()->getRoutes())
        ->filter(fn (Route $r) => str_starts_with($r->uri(), 'api/'))
        ->flatMap(fn (Route $r) => collect($r->methods())
            ->reject(fn ($m) => in_array($m, ['HEAD', 'OPTIONS']))
            // An update route answers PUT and PATCH; the document lists it once, as PUT
            ->reject(fn ($m) => $m === 'PATCH' && in_array('PUT', $r->methods()))
            ->map(fn ($m) => "$m ".normalisePath($r->uri())))
        ->sort()->values()->all();

    expect($documented)->toBe($routes);
});

test('the document declares bearer auth and the error format', function () {
    $spec = json_decode(file_get_contents(base_path('docs/openapi.json')), true);

    expect($spec['openapi'])->toStartWith('3.')
        ->and($spec['components']['securitySchemes'])->toHaveKey('http')
        ->and($spec['info']['description'])->toContain('request_id');
});
